import React, { useEffect, useState } from 'react';
import api from '../services/api';

interface Advisory {
  advisory: string;
  synopsis: string;
  severity: string;
  products: string;
  publishDate: string;
  cves: string[];
  link: string;
}

const PAGE_SIZE = 10;

function exportToCSV(data: Advisory[]) {
  const headers = ['Advisory', 'Synopsis', 'Severity', 'Products', 'Publish Date', 'CVEs', 'Link'];
  const rows = data.map(adv => [
    adv.advisory,
    adv.synopsis,
    adv.severity,
    adv.products,
    adv.publishDate,
    adv.cves && adv.cves.length > 0 ? adv.cves.join('; ') : '-',
    adv.link
  ]);
  const csvContent = [headers, ...rows].map(row => row.map(field => `"${String(field).replace(/"/g, '""')}"`).join(',')).join('\n');
  const blob = new Blob([csvContent], { type: 'text/csv' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = 'rhel_advisories.csv';
  a.click();
  URL.revokeObjectURL(url);
}

const PatchMgmt: React.FC = () => {
  const [advisories, setAdvisories] = useState<Advisory[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [severityFilter, setSeverityFilter] = useState<string>('All');
  const [advisoryFilter, setAdvisoryFilter] = useState('');
  const [synopsisFilter, setSynopsisFilter] = useState('');
  const [productsFilter, setProductsFilter] = useState('');
  const [cveFilter, setCveFilter] = useState('');
  const [dateFrom, setDateFrom] = useState('');
  const [dateTo, setDateTo] = useState('');
  const [search, setSearch] = useState('');
  const [sortBy, setSortBy] = useState<'publishDate' | 'severity'>('publishDate');
  const [sortOrder, setSortOrder] = useState<'asc' | 'desc'>('desc');
  const [page, setPage] = useState(1);

  useEffect(() => {
    setLoading(true);
    setError(null);
    api.get('/patches/redhat')
      .then(res => setAdvisories(res.data))
      .catch(() => setError('Failed to load advisories'))
      .finally(() => setLoading(false));
  }, []);

  // Filtering
  let filtered = advisories.filter(a => {
    // Search box (case-insensitive, matches advisory, synopsis, products, CVEs)
    const searchText = search.trim().toLowerCase();
    if (searchText &&
      !(
        a.advisory.toLowerCase().includes(searchText) ||
        a.synopsis.toLowerCase().includes(searchText) ||
        a.products.toLowerCase().includes(searchText) ||
        (a.cves && a.cves.join(' ').toLowerCase().includes(searchText))
      )
    ) return false;
    // Advanced filters
    if (severityFilter !== 'All' && a.severity !== severityFilter) return false;
    if (advisoryFilter && !a.advisory.toLowerCase().includes(advisoryFilter.toLowerCase())) return false;
    if (synopsisFilter && !a.synopsis.toLowerCase().includes(synopsisFilter.toLowerCase())) return false;
    if (productsFilter && !a.products.toLowerCase().includes(productsFilter.toLowerCase())) return false;
    if (cveFilter && !(a.cves && a.cves.join(' ').toLowerCase().includes(cveFilter.toLowerCase()))) return false;
    if (dateFrom && new Date(a.publishDate) < new Date(dateFrom)) return false;
    if (dateTo && new Date(a.publishDate) > new Date(dateTo)) return false;
    return true;
  });

  // Sorting
  const sorted = [...filtered].sort((a, b) => {
    if (sortBy === 'publishDate') {
      const dateA = new Date(a.publishDate).getTime();
      const dateB = new Date(b.publishDate).getTime();
      return sortOrder === 'asc' ? dateA - dateB : dateB - dateA;
    } else if (sortBy === 'severity') {
      const sevOrder = ['Critical', 'Important', 'Moderate', 'Low', 'Unknown'];
      const idxA = sevOrder.indexOf(a.severity);
      const idxB = sevOrder.indexOf(b.severity);
      return sortOrder === 'asc' ? idxA - idxB : idxB - idxA;
    }
    return 0;
  });

  // Pagination
  const totalPages = Math.ceil(sorted.length / PAGE_SIZE);
  const paginated = sorted.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE);

  // Unique severities for filter dropdown
  const severities = Array.from(new Set(advisories.map(a => a.severity))).filter(Boolean);

  // Handle sorting
  const handleSort = (col: 'publishDate' | 'severity') => {
    if (sortBy === col) {
      setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc');
    } else {
      setSortBy(col);
      setSortOrder('desc');
    }
  };

  // Handle page change
  const handlePageChange = (newPage: number) => {
    if (newPage >= 1 && newPage <= totalPages) setPage(newPage);
  };

  // Reset to page 1 when filter or sort changes
  useEffect(() => { setPage(1); }, [severityFilter, advisoryFilter, synopsisFilter, productsFilter, cveFilter, dateFrom, dateTo, search, sortBy, sortOrder]);

  return (
    <div style={{ margin: '2rem 0' }}>
      <h2>RHEL Security Advisories</h2>
      <div style={{ margin: '1rem 0', display: 'flex', gap: '1rem', alignItems: 'center' }}>
        <input
          type="text"
          placeholder="Search..."
          value={search}
          onChange={e => setSearch(e.target.value)}
          style={{ padding: '4px 8px', minWidth: 180 }}
        />
        <button onClick={() => exportToCSV(sorted)} style={{ padding: '4px 12px' }}>Export CSV</button>
      </div>
      {loading && <div>Loading advisories...</div>}
      {error && <div style={{ color: 'red' }}>{error}</div>}
      {!loading && !error && (
        <>
          <div style={{ overflowX: 'auto', marginTop: '2rem' }}>
            <table style={{ borderCollapse: 'collapse', width: '100%' }}>
              <thead>
                <tr>
                  <th style={{ padding: '8px', borderBottom: '1px solid #ccc' }}>
                    <input
                      type="text"
                      placeholder="Advisory"
                      value={advisoryFilter}
                      onChange={e => setAdvisoryFilter(e.target.value)}
                      style={{ width: '90px' }}
                    />
                  </th>
                  <th style={{ padding: '8px', borderBottom: '1px solid #ccc' }}>
                    <input
                      type="text"
                      placeholder="Synopsis"
                      value={synopsisFilter}
                      onChange={e => setSynopsisFilter(e.target.value)}
                      style={{ width: '120px' }}
                    />
                  </th>
                  <th style={{ padding: '8px', borderBottom: '1px solid #ccc', minWidth: 120 }}>
                    <select value={severityFilter} onChange={e => setSeverityFilter(e.target.value)} style={{ minWidth: 100 }}>
                      <option value="All">All Severities</option>
                      {severities.map(s => (
                        <option key={s} value={s}>{s}</option>
                      ))}
                    </select>
                    <span
                      style={{ cursor: 'pointer', marginLeft: 4 }}
                      onClick={() => handleSort('severity')}
                    >
                      {sortBy === 'severity' ? (sortOrder === 'asc' ? '▲' : '▼') : ''}
                    </span>
                  </th>
                  <th style={{ padding: '8px', borderBottom: '1px solid #ccc' }}>
                    <input
                      type="text"
                      placeholder="Products"
                      value={productsFilter}
                      onChange={e => setProductsFilter(e.target.value)}
                      style={{ width: '120px' }}
                    />
                  </th>
                  <th style={{ padding: '8px', borderBottom: '1px solid #ccc', minWidth: 160 }}>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
                      <input
                        type="text"
                        placeholder="From (yyyy-mm-dd)"
                        value={dateFrom}
                        onChange={e => setDateFrom(e.target.value)}
                        style={{ width: '110px', marginBottom: 2 }}
                      />
                      <input
                        type="text"
                        placeholder="To (yyyy-mm-dd)"
                        value={dateTo}
                        onChange={e => setDateTo(e.target.value)}
                        style={{ width: '110px' }}
                      />
                      <span
                        style={{ cursor: 'pointer', marginLeft: 4 }}
                        onClick={() => handleSort('publishDate')}
                      >
                        {sortBy === 'publishDate' ? (sortOrder === 'asc' ? '▲' : '▼') : ''}
                      </span>
                    </div>
                  </th>
                  <th style={{ padding: '8px', borderBottom: '1px solid #ccc' }}>
                    <input
                      type="text"
                      placeholder="CVEs"
                      value={cveFilter}
                      onChange={e => setCveFilter(e.target.value)}
                      style={{ width: '100px' }}
                    />
                  </th>
                  <th style={{ padding: '8px', borderBottom: '1px solid #ccc' }}>Link</th>
                </tr>
              </thead>
              <tbody>
                {paginated.map(adv => (
                  <tr key={adv.advisory}>
                    <td style={{ padding: '8px', borderBottom: '1px solid #eee' }}>{adv.advisory}</td>
                    <td style={{ padding: '8px', borderBottom: '1px solid #eee' }}>{adv.synopsis}</td>
                    <td style={{ padding: '8px', borderBottom: '1px solid #eee' }}>{adv.severity}</td>
                    <td style={{ padding: '8px', borderBottom: '1px solid #eee' }}>{adv.products}</td>
                    <td style={{ padding: '8px', borderBottom: '1px solid #eee' }}>{adv.publishDate}</td>
                    <td style={{ padding: '8px', borderBottom: '1px solid #eee' }}>{adv.cves && adv.cves.length > 0 ? adv.cves.join(', ') : '-'}</td>
                    <td style={{ padding: '8px', borderBottom: '1px solid #eee' }}>
                      <a href={adv.link} target="_blank" rel="noopener noreferrer">View</a>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          {/* Pagination Controls */}
          <div style={{ marginTop: '1rem', display: 'flex', justifyContent: 'center', alignItems: 'center', gap: '1rem' }}>
            <button onClick={() => handlePageChange(page - 1)} disabled={page === 1}>&lt; Prev</button>
            <span>Page {page} of {totalPages}</span>
            <button onClick={() => handlePageChange(page + 1)} disabled={page === totalPages}>Next &gt;</button>
          </div>
        </>
      )}
    </div>
  );
};

export default PatchMgmt;
